#include <stdio.h>
#include <string.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat a;
    strcpy(a.name, "{who}");
    a.fish = {f1};
    printf("%s 吃了 %d 条喵\n", a.name, a.fish);
    return 0;
}
